const lockOfficeEventSealer = `-- name: LockOfficeEventSealer :exec

SELECT pg_advisory_xact_lock(1963687)
`

// Office event stream (DENE-1963). Rows are written by triggers (migration
// 687); these queries seal them, fan them out to Bots and read them back.
// One sealer at a time across every server process, so stream_seq is handed
// out in the order the seals commit.
func (q *Queries) LockOfficeEventSealer(ctx context.Context) error {
	_, err := q.db.Exec(ctx, lockOfficeEventSealer)
	return err
}

const markOfficeDeliveryRetry = `-- name: MarkOfficeDeliveryRetry :exec
UPDATE office_event_delivery SET
    status = CASE WHEN sent_at IS NULL THEN 'pending' ELSE 'sent' END,
    attempts = attempts + 1,
    last_attempt_at = now(),
    last_error = $1,
    next_attempt_at = $2,
    updated_at = now()
WHERE id = $3 AND status = 'sending'
`

type MarkOfficeDeliveryRetryParams struct {
	LastError     string             `json:"last_error"`
	NextAttemptAt pgtype.Timestamptz `json:"next_attempt_at"`
	ID            int64              `json:"id"`
}

func (q *Queries) MarkOfficeDeliveryRetry(ctx context.Context, arg MarkOfficeDeliveryRetryParams) error {
	_, err := q.db.Exec(ctx, markOfficeDeliveryRetry, arg.LastError, arg.NextAttemptAt, arg.ID)
	return err
}

const markOfficeDeliverySent = `-- name: MarkOfficeDeliverySent :exec
UPDATE office_event_delivery SET
    status = 'sent',
    attempts = attempts + 1,
    last_attempt_at = now(),
    sent_at = COALESCE(sent_at, now()),
    last_error = '',
    next_attempt_at = $1,
    updated_at = now()
WHERE id = $2 AND status = 'sending'
`

type MarkOfficeDeliverySentParams struct {
	NextAttemptAt pgtype.Timestamptz `json:"next_attempt_at"`
	ID            int64              `json:"id"`
}

// HTTP 200. Not a receipt: the row stays open and is resent at next_attempt_at
// unless the Bot acknowledges it first.
func (q *Queries) MarkOfficeDeliverySent(ctx context.Context, arg MarkOfficeDeliverySentParams) error {
	_, err := q.db.Exec(ctx, markOfficeDeliverySent, arg.NextAttemptAt, arg.ID)
	return err
}

const markOfficeDeliveryUncertain = `-- name: MarkOfficeDeliveryUncertain :exec
UPDATE office_event_delivery SET
    status = 'sent',
    attempts = attempts + 1,
    last_attempt_at = now(),
    sent_at = COALESCE(sent_at, now()),
    uncertain_at = now(),
    last_error = $1,
    next_attempt_at = $2,
    updated_at = now()
WHERE id = $3 AND status = 'sending'
`

type MarkOfficeDeliveryUncertainParams struct {
	LastError     string             `json:"last_error"`
	NextAttemptAt pgtype.Timestamptz `json:"next_attempt_at"`
	ID            int64              `json:"id"`
}

// The request went out but the answer was lost: the Bot may already have it.
// Treated as sent, not failed: the next attempt waits the receipt timeout (a
// receipt that arrives meanwhile closes it) and goes out marked reconcile,
// so the Bot answers from its inbox instead of acting on it twice.
func (q *Queries) MarkOfficeDeliveryUncertain(ctx context.Context, arg MarkOfficeDeliveryUncertainParams) error {
	_, err := q.db.Exec(ctx, markOfficeDeliveryUncertain, arg.LastError, arg.NextAttemptAt, arg.ID)
	return err
}

